      h('div',{className:'rd-home-now'},snap.current?h(DFL.DialogButton,{className:'rd-home-now-button',onClick:onNow},h('div',{className:'rd-row'},h('img',{className:'rd-row-art',src:snap.artUrl||RD_ICON,draggable:false}),h('div',{className:'rd-grow'},h('div',{className:'rd-mini-kind'},'NOW PLAYING'),h('div',{className:'rd-title'},snap.current.title||'Untitled'),h('div',{className:'rd-meta'},snap.current.artist||snap.current.album||'')),h('span',{className:'rd-pill'},snap.state==='playing'?'PLAYING':'OPEN'))):h('div',null,h('div',{className:'rd-title'},'Nothing playing'),h('div',{className:'rd-meta rd-wrap',style:{marginTop:5}},'Pick anything below. ResonaDeck keeps the player alive while you browse.')))
