function CatalogCardV3({item,role,view,onOpen,onGamepadDirection,index,onNearEnd}){
  const portrait=role==='audiobooks'&&(view==='books'||view==='albums'||view==='home'||view==='recently_added');
  const durationMs=Number(item.durationMs||0)||Number(item.duration||0)*1000;
  const pct=(Number(item.viewOffset||0)>0&&durationMs>0)?clamp(Number(item.viewOffset)/durationMs*100,0,100):0;
  const subtitle=item.artist||item.album||(view==='authors'||view==='artists'?'Creator':view==='collections'?'Collection':roleInfo(role).label);
  return h(DFL.DialogButton,{focusable:true,className:'rd-media-card','data-rd-catalog-card':String(index),onGamepadDirection,onFocus:()=>onNearEnd?.(index),onClick:()=>onOpen?.(item)},
    h(Artwork,{path:item.thumb||item.parentThumb,className:`rd-media-cover ${portrait?'portrait':'square'}`,role,label:item.title,mode:portrait?'portrait':'square'}),
    h('div',{className:'rd-media-card-title'},item.title||'Untitled'),
    h('div',{className:'rd-media-card-sub'},subtitle||''),
    pct>0?h('div',{className:'rd-media-progress'},h('i',{style:{width:`${pct}%`}})):null
  );
}
