// ---------------------------------------------------------------------------
// 0.5.0 Fusion UX
// These components intentionally sit beside the older implementation so the
// proven auth/PIN/bootstrap paths stay untouched while the everyday media UX
// can be replaced as a unit.
// ---------------------------------------------------------------------------
const RD_ART_GENERATION='v7-registry';
const RD_ART_STORE_KEY_V81='__RESONADECK_ARTWORK_REGISTRY_V84__';
const rdArtRetryV5=new Map();
function rdLongFormRoleV5(role){return role==='audiobooks'||role==='podcasts'||role==='other';}
function rdFallbackArtworkV97(role,kind=''){const r=String(role||'').toLowerCase(),k=String(kind||'').toLowerCase();if(r==='audiobooks'||k==='audiobook')return RD_FALLBACK_AUDIOBOOKS_V97;if(r==='podcasts'||k==='podcast')return RD_FALLBACK_PODCASTS_V97;if(r==='music'||k==='music')return RD_FALLBACK_MUSIC_V97;return RD_ICON;}
function rdKindForRoleV5(role){return role==='audiobooks'?'audiobook':role==='podcasts'?'podcast':'music';}
function rdArtModeV5(role,detail=false){return role==='audiobooks'?(detail?'portrait-book-v85-detail':'portrait-book-v85'):(detail?'square':'square-card');}
function rdMediaTypeV5(item){return String(item?.type||item?.mediaType||'').toLowerCase();}
function rdItemKeyV5(item,i=0){return String(item?.ratingKey||item?.key||`${item?.title||'item'}-${i}`);}
function rdArtPathV5(item){return String(item?.thumb||item?.parentThumb||item?.grandparentThumb||item?.art||item?.parentArt||item?.grandparentArt||'');}
function rdPctV5(item){const durationMs=Number(item?.durationMs||0)||Number(item?.duration||0)*1000;const offset=Number(item?.viewOffset||item?.resumeOffsetMs||0);return durationMs>0&&offset>0?clamp(offset/durationMs*100,0,100):0;}
function rdGreetingV5(){const h=new Date().getHours();return h<5?'Late night listening':h<12?'Good morning':h<17?'Good afternoon':h<22?'Good evening':'Night listening';}
function rdMergeUniqueV5(...groups){const out=[],seen=new Set();for(const rows of groups){for(const item of (rows||[])){const role=String(item?.libraryRole||'');const k=`${role}:${rdItemKeyV5(item)}`;if(seen.has(k))continue;seen.add(k);out.push(item);}}return out;}
function rdDedupPodcastShowsV5(items){const out=[],seen=new Set();for(const item of items||[]){const title=String(item?.title||item?.album||'').trim().toLowerCase();const artist=String(item?.artist||'').trim().toLowerCase();const key=`${title}|${artist}`;if(key==='|'||seen.has(key))continue;seen.add(key);out.push(item);}return out;}
async function rdResumeLongV5(item,role){if(role==='audiobooks'){const r=await call('get_book_manifest',String(item.ratingKey),false);if(r?.success&&r.manifest?.files?.length){await audioEngine.setBook(r.manifest,true,Number(r.manifest.resume?.positionMs||item.viewOffset||0));return;}}const r=await call('get_children',String(item.ratingKey));const q=r?.tracks||[];q.forEach(t=>t.libraryRole=role);if(!q.length){item.libraryRole=role;await audioEngine.setQueue([item],0,rdKindForRoleV5(role),true);return;}const idx=Math.max(0,q.findIndex(t=>String(t.ratingKey)===String(item.resumeTrackRatingKey)));await audioEngine.setQueue(q,idx,rdKindForRoleV5(role),true,item.resumeOffsetMs?Number(item.resumeOffsetMs)/1000:null);}
async function rdOpenMediaV5(item,role,{directTrack=false,playlist=false}={}){if(!item)return;if(playlist){await playPlaylist(item);return;}item.libraryRole=role;if(item.resumeTrackRatingKey&&rdLongFormRoleV5(role)){await rdResumeLongV5(item,role);return;}if(directTrack||rdMediaTypeV5(item)==='track'){await playTrack(item,rdKindForRoleV5(role),role);return;}await playCollection(item,rdKindForRoleV5(role),role);}
function rdFocusElementV5(el){try{return rdNativeTakeFocus(el);}catch(_){try{el?.focus?.({preventScroll:true});return true}catch(__){return false}}}
function rdFmtMsV75(ms){return fmt(Math.max(0,Number(ms||0))/1000);}
function rdFmtBytesV75(bytes){const n=Math.max(0,Number(bytes||0));if(!n)return '—';if(n>=1073741824)return `${(n/1073741824).toFixed(n>=10737418240?0:1)} GB`;if(n>=1048576)return `${(n/1048576).toFixed(n>=104857600?0:1)} MB`;if(n>=1024)return `${Math.round(n/1024)} KB`;return `${Math.round(n)} B`;}
