function SearchGridV5({group,items,roleFallback='music',onOpen}){
  const root=R.useRef(null),perRow=4;
  const nav=(index,event)=>{
    const d=rdDir(event);
    if(d!==RD_DIR_UP&&d!==RD_DIR_DOWN)return false;
    const target=d===RD_DIR_UP?index-perRow:index+perRow;
    if(target<0||target>=items.length)return false;
    const el=root.current?.querySelector?.(`[data-rd-search-card="${group}-${target}"]`);
    if(el){rdFocusElementV5(el);return true;}
    return false;
  };
  const rows=[];
  for(let i=0;i<items.length;i+=perRow){
    const rowItems=items.slice(i,i+perRow).map((item,j)=>{
      const idx=i+j;
      const role=item.libraryRole||roleFallback;
      const portrait=role==='audiobooks'&&group!=='artists';
      return h(DFL.DialogButton,{
        key:rdItemKeyV5(item,idx),
        className:'rd-v5-card',
        'data-rd-search-card':`${group}-${idx}`,
        onGamepadDirection:e=>nav(idx,e)||rdManagerDirectionalV910(e),
        onClick:()=>onOpen(item,role,group)
      },
        h(ArtworkV5,{path:rdArtPathV5(item),item,className:`rd-v5-cover ${portrait?'portrait':'square'}`,role,mode:portrait?rdArtModeV5('audiobooks',false):'square-card'}),
        h('div',{className:'rd-v5-card-title'},item.title||'Untitled'),
        h('div',{className:'rd-v5-card-sub'},item.artist||item.album||roleInfo(role).label)
      );
    });
    rows.push(h(DFL.Focusable,{key:`srow-${i}`,'flow-children':'right',className:'rd-v5-grid-row'},rowItems));
  }
  return h('div',{ref:root},h(DFL.Focusable,{'flow-children':'down',className:'rd-v5-grid'},rows));
}
// 0.9.44 RC: warm only the first visible search tracks without blocking UI.
