async function rdQamQueueTracksV949(item,role='music'){
  if(role!=='music')return [];
  if(rdMediaTypeV5(item)==='track')return [{...item,libraryRole:'music'}];
  const key=String(item?.ratingKey||'');if(!key)return [];
  let tracks=[];
  if(rdMediaTypeV5(item)==='artist'){
    const result=await call('get_artist_tracks',key);
    tracks=result?.tracks||[];
  }else if(rdMediaTypeV5(item)==='playlist'){
    const result=await call('get_playlist_items',key);
    tracks=result?.tracks||result?.items||[];
  }else{
    const result=await call('get_children',key);
    tracks=result?.tracks||[];
  }
  return tracks.filter(x=>rdMediaTypeV5(x)==='track').slice(0,100).map(x=>({...x,libraryRole:'music'}));
}
